#   * $wgScriptExtension dropped — removed from MediaWiki in 1.26, ignored since.
# Everything else is unchanged from the legacy configuration.

# Protect against web entry
if (!defined('MEDIAWIKI')) {
    exit;
}

/**
 * Fail loudly at startup on a missing secret rather than silently running with an empty one.
 */
function gahkEnv($name, $default = null)
{
    $value = getenv($name);
    if ($value === false || $value === '') {
        if ($default !== null) {
            return $default;
        }
        die("Configuration error: environment variable $name is not set.\n");
    }
    // Reject un-substituted placeholders like "<openssl rand -hex 32>" or "<from step 2>". A quoted
    // heredoc copies these in verbatim, and a non-empty value otherwise sails straight through —
    // which for $wgSecretKey means a predictable key silently weakening CSRF and session security.
    if ($value[0] === '<' && substr($value, -1) === '>') {
        die("Configuration error: $name still holds the placeholder '$value'.\n");
    }
    return $value;
}

## Uncomment this to disable output compression
# $wgDisableOutputCompression = true;

$wgSitename = "Gahk Wiki";
$wgMetaNamespace = "Gahk_Wiki";

## The wiki has its own host, wiki.gahk.dk (it used to be gahk.dk/wiki behind a Traefik
## `stripprefix`), and is served from its root with no proxy rewriting: the scripts at /index.php,
## /load.php, /api.php, uploads at /images/…, and pages at /wiki/<title> (MediaWiki's standard short
## URLs; the rewrite is in apache-wiki.conf). gahk.dk forwards its old /wiki/… addresses here.
$wgScriptPath = "";
$wgArticlePath = "/wiki/$1";

## The protocol and server name to use in fully-qualified URLs.
$wgServer = gahkEnv('MW_SERVER', 'https://wiki.gahk.dk');

## Cookies stay on this host: no Domain attribute, so the browser never sends them to gahk.dk (other,
## shared hosting) or intern.gahk.dk. Login is the wiki's own (GahkAuthLogin); nothing is shared with
## the intranet. Secure whenever the wiki is served over https, which production always is. Set
## explicitly rather than left to 'detect', since behind the proxy Apache itself only sees http.
$wgCookieDomain = "";
$wgCookieSecure = str_starts_with($wgServer, 'https://');
## Logs everyone out once, at the move: the wiki's old cookies were host-only on gahk.dk, so browsers
## keep sending them to the public site's shared hosting until they expire (a "remember me" token
## lasts 180 days). A new token version makes every one of them worthless. Changing it again logs
## everyone out again.
$wgAuthenticationTokenVersion = "wiki.gahk.dk";

## The relative URL path to the skins directory
$wgStylePath = "$wgScriptPath/skins";

$wgLogo = "$wgScriptPath/resources/assets/logo.png";

## UPO means: this is also a user preference option

$wgEnableEmail = true;
$wgEnableUserEmail = true; # UPO

$wgEmergencyContact = "it@gahk.dk";
$wgPasswordSender = "it@gahk.dk";

$wgEnotifUserTalk = false; # UPO
$wgEnotifWatchlist = false; # UPO
$wgEmailAuthentication = true;

## Database settings
$wgDBtype = "mysql";
$wgDBserver = gahkEnv('MW_DB_HOST');
$wgDBname = gahkEnv('MW_DB_NAME', 'gahk_wiki');
$wgDBuser = gahkEnv('MW_DB_USER', 'wiki');
$wgDBpassword = gahkEnv('MW_DB_PASSWORD');

# MySQL specific settings — the imported wiki.sql keeps the legacy `wiki` table prefix.
$wgDBprefix = "wiki";

# Table options for installation/update. InnoDB: the source database was converted from MyISAM
# before the 2026-08-04 dump, so every imported table is already InnoDB.
$wgDBTableOptions = "ENGINE=InnoDB, DEFAULT CHARSET=binary";

## Shared memory settings
$wgMainCacheType = CACHE_NONE;
$wgMemCachedServers = [];

# InstantCommons allows wiki to use images from http://commons.wikimedia.org
$wgUseInstantCommons = false;

$wgShellLocale = "en_US.utf8";

# Site language code, should be one of the list in ./languages/Names.php
$wgLanguageCode = "da";

# Rotate these at deploy time; the legacy values are considered compromised (scope §5).
$wgSecretKey = gahkEnv('MW_SECRET_KEY');
$wgUpgradeKey = gahkEnv('MW_UPGRADE_KEY');

## Default skin
$wgDefaultSkin = "vector";

$wgRightsPage = ""; # Set to the title of a wiki page that describes your license/copyright
$wgRightsUrl = "";
$wgRightsText = "";
$wgRightsIcon = "";

# Path to the GNU diff3 utility. Used for conflict resolution.
$wgDiff3 = "";

# The following permissions were set based on your choice in the installer.
# NOTE: read=false means the wiki is fully private — anonymous users cannot read any page. Combined
# with GahkAuthLogin being the only primaryauth provider and strict()===true, an unreachable Postgres
# locks everyone out, sysops included. See CUTOVER.md Phase 5A for the break-glass procedure.
$wgGroupPermissions['*']['read'] = false;
$wgGroupPermissions['*']['edit'] = false;


# End of automatically generated settings.
# Add more configuration options below.

$wgGroupPermissions['*']['createaccount'] = false;
$wgGroupPermissions['*']['autocreateaccount'] = true;
$wgGroupPermissions['sysop']['createaccount'] = true;

// Use GAHK alumneliste

$wgEnableUploads = true;
$wgFileExtensions[] = 'doc';
$wgFileExtensions[] = 'docx';
$wgFileExtensions[] = 'xls';
$wgFileExtensions[] = 'xlsx';
$wgFileExtensions[] = 'odt';
$wgFileExtensions[] = 'ods';
$wgFileExtensions[] = 'pdf';

# Deliberately BELOW the Dockerfile's upload_max_filesize (72M), not equal to it. MediaWiki checks
# the size only after PHP has accepted the file, so anything PHP rejects never reaches this check —
# and PHP rejects silently, leaving "the file you uploaded seems to be empty" as the only clue. With
# a margin, MediaWiki is always the one that answers, and it says what the limit actually is.
#
# Without this line MediaWiki's default is 100M, i.e. *above* PHP's ceiling, which is the wrong way
# round: every upload between the two limits would fail with the unhelpful message instead of the
# helpful one.
$wgMaxUploadSize = 64 * 1024 * 1024;


wfLoadExtension('ShowRealUsernames');
wfLoadExtension('RealNames');
wfLoadExtension('GahkAuthLogin');

wfLoadSkin('Vector');
wfLoadSkin('MonoBook');
wfLoadSkin('Modern');
wfLoadSkin('CologneBlue');

